import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'

import { ZnDesktopErrorBoundary } from './error-boundary'
import { initializeZnDesktopI18n } from './i18n'
import { ZnWorkbench } from './workbench'
import './styles.css'
import './liquid-performance.css'
// Presentation comes from the vendored open-claude-ui snapshot: CDS design
// tokens first, then the Tailwind utilities the vendored components'
// classNames resolve to (generated by the bundle script; gitignored).
// No ZN-owned visual-design stylesheet remains: styles.css above is only
// layout glue plus the CI-pinned behaviour anchors (compact sidebar,
// reduced-motion, focus-visible).
import '../../../../vendor/open-claude-ui/code-examples/cds-theme.css'
import './cds-tailwind.generated.css'

document.title = 'ZN'

async function renderZnDesktop(): Promise<void> {
  await initializeZnDesktopI18n()
  const root = document.getElementById('root')
  if (!root) throw new Error('ZN renderer root is missing')

  createRoot(root).render(
    <StrictMode>
      <ZnDesktopErrorBoundary>
        <ZnWorkbench />
      </ZnDesktopErrorBoundary>
    </StrictMode>
  )
}

void renderZnDesktop()
